-- lovable-cron-fallback-reviewed: Closed browsers cannot trigger deletion; no delayed workflow provider enabled. Cleanup only runs while demo sessions exist and unschedules after drain, with strict access expiry at 15 minutes.
CREATE TABLE public.investor_demo_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT(now()+interval '15 minutes'),state jsonb NOT NULL DEFAULT '{"attempts":[],"attendance":{},"classes":[],"announcements":[],"completedVideos":[],"goals":{"speed":2,"hard":5,"medium":10}}'::jsonb);
GRANT ALL ON public.investor_demo_sessions TO service_role;
ALTER TABLE public.investor_demo_sessions ENABLE ROW LEVEL SECURITY;
CREATE INDEX investor_demo_expiration ON public.investor_demo_sessions(expires_at);
CREATE FUNCTION public.investor_demo_cleanup() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE j bigint; BEGIN PERFORM pg_advisory_xact_lock(7715401); DELETE FROM public.investor_demo_sessions WHERE expires_at<=now(); IF NOT EXISTS(SELECT 1 FROM public.investor_demo_sessions) THEN FOR j IN SELECT jobid FROM cron.job WHERE jobname='investor-demo-expiry' LOOP PERFORM cron.unschedule(j); END LOOP; END IF; END $$;
REVOKE ALL ON FUNCTION public.investor_demo_cleanup() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.investor_demo_cleanup() TO service_role;
CREATE FUNCTION public.investor_demo_start(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions,pg_temp AS $$ DECLARE r public.investor_demo_sessions; BEGIN IF _token IS NULL OR _token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid demo token'; END IF; PERFORM pg_advisory_xact_lock(7715401); DELETE FROM public.investor_demo_sessions WHERE expires_at<=now(); SELECT * INTO r FROM public.investor_demo_sessions WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex'); IF FOUND THEN RETURN jsonb_build_object('expiresAt',r.expires_at,'state',r.state); END IF; IF(SELECT count(*) FROM public.investor_demo_sessions)>=100 THEN RAISE EXCEPTION 'Demo is busy. Please try again shortly.'; END IF; INSERT INTO public.investor_demo_sessions(token_hash) VALUES(encode(extensions.digest(_token,'sha256'),'hex')) RETURNING * INTO r; IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='investor-demo-expiry') THEN PERFORM cron.schedule('investor-demo-expiry','* * * * *','SELECT public.investor_demo_cleanup();'); END IF; RETURN jsonb_build_object('expiresAt',r.expires_at,'state',r.state); END $$;
REVOKE ALL ON FUNCTION public.investor_demo_start(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.investor_demo_start(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.investor_demo_state(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions,pg_temp AS $$ DECLARE r public.investor_demo_sessions; BEGIN IF _token IS NULL OR _token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid demo token'; END IF; SELECT * INTO r FROM public.investor_demo_sessions WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND expires_at>now(); IF NOT FOUND THEN RAISE EXCEPTION 'Demo expired'; END IF; RETURN jsonb_build_object('expiresAt',r.expires_at,'state',r.state); END $$;
REVOKE ALL ON FUNCTION public.investor_demo_state(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.investor_demo_state(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.investor_demo_action(_token text,_action text,_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions,pg_temp AS $$ DECLARE r public.investor_demo_sessions; s jsonb; n integer; BEGIN IF _token IS NULL OR _token !~ '^[a-f0-9]{64}$' OR _payload IS NULL OR jsonb_typeof(_payload)<>'object' OR octet_length(_payload::text)>4096 THEN RAISE EXCEPTION 'Invalid demo request'; END IF; SELECT * INTO r FROM public.investor_demo_sessions WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND expires_at>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Demo expired'; END IF; s:=r.state;
CASE _action
WHEN 'attempt' THEN IF COALESCE(_payload->>'question','') !~ '^[0-5]$' OR COALESCE(_payload->>'answer','') NOT IN('A','B','C','D') OR COALESCE(_payload->>'seconds','') !~ '^[0-9]{1,4}$' THEN RAISE EXCEPTION 'Invalid answer'; END IF; IF jsonb_array_length(s->'attempts')>=200 THEN RAISE EXCEPTION 'Demo attempt limit reached'; END IF; n:=(_payload->>'question')::integer; s:=jsonb_set(s,'{attempts}',(s->'attempts')||jsonb_build_array(jsonb_build_object('question',n,'correct',(_payload->>'answer')=(ARRAY['B','C','A','D','B','C'])[n+1],'seconds',LEAST(3600,(_payload->>'seconds')::integer),'createdAt',now())));
WHEN 'attendance' THEN IF COALESCE(_payload->>'student','') NOT IN('Alex Morgan','Mia Chen','Noah Patel','Emma Wilson','Liam Kim') OR COALESCE(_payload->>'status','') NOT IN('present','late','absent','sick','excused') THEN RAISE EXCEPTION 'Invalid attendance'; END IF; s:=jsonb_set(s,ARRAY['attendance',_payload->>'student'],to_jsonb(_payload->>'status'),true);
WHEN 'class' THEN IF COALESCE(length(trim(_payload->>'name')),0) NOT BETWEEN 1 AND 60 OR jsonb_array_length(s->'classes')>=10 THEN RAISE EXCEPTION 'Invalid class'; END IF; s:=jsonb_set(s,'{classes}',(s->'classes')||jsonb_build_array(jsonb_build_object('name',trim(_payload->>'name'))));
WHEN 'announcement' THEN IF COALESCE(length(trim(_payload->>'text')),0) NOT BETWEEN 1 AND 500 OR jsonb_array_length(s->'announcements')>=10 THEN RAISE EXCEPTION 'Invalid announcement'; END IF; s:=jsonb_set(s,'{announcements}',(s->'announcements')||jsonb_build_array(jsonb_build_object('text',trim(_payload->>'text'),'createdAt',now())));
WHEN 'video' THEN IF COALESCE(_payload->>'id','') NOT IN('exponents','linear','quadratic','desmos','geometry') THEN RAISE EXCEPTION 'Invalid lesson'; END IF; IF NOT(s->'completedVideos') ? (_payload->>'id') THEN s:=jsonb_set(s,'{completedVideos}',(s->'completedVideos')||jsonb_build_array(_payload->>'id')); END IF;
WHEN 'goals' THEN IF COALESCE(_payload->>'speed','') !~ '^[1-9][0-9]?$' OR COALESCE(_payload->>'hard','') !~ '^[1-9][0-9]?$' OR COALESCE(_payload->>'medium','') !~ '^[1-9][0-9]?$' THEN RAISE EXCEPTION 'Invalid goals'; END IF; s:=jsonb_set(s,'{goals}',jsonb_build_object('speed',(_payload->>'speed')::integer,'hard',(_payload->>'hard')::integer,'medium',(_payload->>'medium')::integer));
ELSE RAISE EXCEPTION 'Unknown demo action'; END CASE; UPDATE public.investor_demo_sessions SET state=s WHERE id=r.id; RETURN jsonb_build_object('expiresAt',r.expires_at,'state',s); END $$;
REVOKE ALL ON FUNCTION public.investor_demo_action(text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.investor_demo_action(text,text,jsonb) TO anon,authenticated,service_role;
CREATE FUNCTION public.investor_demo_end(_token text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions,pg_temp AS $$ BEGIN IF _token IS NULL OR _token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid demo token'; END IF; PERFORM pg_advisory_xact_lock(7715401); DELETE FROM public.investor_demo_sessions WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex'); PERFORM public.investor_demo_cleanup(); END $$;
REVOKE ALL ON FUNCTION public.investor_demo_end(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.investor_demo_end(text) TO anon,authenticated,service_role;
COMMENT ON TABLE public.investor_demo_sessions IS 'Isolated public demo capability sessions, no real tenant data or auth users. Hard expiry 15 minutes; cleanup wakes on start and unschedules after drain.';